using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the web_search tool.
        2. Save key findings using the save_note tool.
        3. Perform multiple searches to gather comprehensive information.
        4. After researching, provide a concise summary of your findings.
        Always search at least 2-3 different aspects of the topic before summarizing.
        """,
    Tools = [
        AIFunctionFactory.Create(researchTools.WebSearch),
        AIFunctionFactory.Create(researchTools.SaveNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ],
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Saved Notes ---");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"• {note}");
}

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a given query. Returns search result snippets.")]
    public string WebSearch([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // In production, replace with a real search API (e.g., Bing Search).
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        return $"""
            Search results for "{query}":
            1. "{query}" - Wikipedia overview: Provides a comprehensive introduction to the topic including history, key concepts, and notable developments.
            2. Recent news: Latest developments and breakthroughs related to {query} from the past month, including expert opinions and industry analysis.
            3. Academic perspective: Peer-reviewed research highlights the significance of {query} in the broader field, with emphasis on methodology and findings.
            """;
    }

    [Description("Save an important finding or note from research for later reference.")]
    public string SaveNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved notes from the current research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return "Saved notes:\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

